# Expected values are SymPy's outputs for the same calls (iterables).

skip_unless_full_tests()

fmt1 <- function(v) if (is.character(v)) paste0("'", v, "'") else if (is.logical(v)) (if (v) "True" else "False") else format(v, scientific = FALSE)
fmt <- function(r) {
  if (is.null(r)) return("[]")
  if (is.atomic(r) && !is.null(names(r)) && !length(r)) return("{}")
  if (is.list(r) && length(r) == 2L && is.atomic(r[[1L]]) && length(r[[1L]]) == 1L && is.null(names(r[[1L]])) && !is.null(names(r[[2L]]))) return(paste0("[", fmt1(r[[1L]]), ", ", fmt(r[[2L]]), "]"))
  if (is.atomic(r) && !is.null(names(r)) && all(nzchar(names(r))))
    return(paste0("{", paste(paste0(vapply(names(r), function(k) if (grepl("^-?[0-9]+$", k)) k else paste0("'", k, "'"), ""), ": ", vapply(r, fmt1, "")), collapse = ", "), "}"))
  if (is.list(r)) return(paste0("[", paste(vapply(r, fmt, ""), collapse = ", "), "]"))
  if (is.character(r) && length(r) == 1L && isTRUE(attr(r, "scalar"))) return(fmt1(r))
  if (length(r) == 1L && !is.null(attr(r, "scalar"))) return(fmt1(r))
  paste0("[", paste(vapply(r, fmt1, ""), collapse = ", "), "]")
}

test_that("iterables match SymPy", {
  expect_equal(fmt(partitions(6)), "[{6: 1}, {5: 1, 1: 1}, {4: 1, 2: 1}, {4: 1, 1: 2}, {3: 2}, {3: 1, 2: 1, 1: 1}, {3: 1, 1: 3}, {2: 3}, {2: 2, 1: 2}, {2: 1, 1: 4}, {1: 6}]")
  expect_equal(fmt(partitions(6, m = 2)), "[{6: 1}, {5: 1, 1: 1}, {4: 1, 2: 1}, {3: 2}]")
  expect_equal(fmt(partitions(6, k = 2)), "[{2: 3}, {2: 2, 1: 2}, {2: 1, 1: 4}, {1: 6}]")
  expect_equal(fmt(partitions(7, m = 3, k = 3)), "[{3: 2, 1: 1}, {3: 1, 2: 2}]")
  expect_equal(fmt(partitions(6, size = TRUE)), "[[1, {6: 1}], [2, {5: 1, 1: 1}], [2, {4: 1, 2: 1}], [3, {4: 1, 1: 2}], [2, {3: 2}], [3, {3: 1, 2: 1, 1: 1}], [4, {3: 1, 1: 3}], [3, {2: 3}], [4, {2: 2, 1: 2}], [5, {2: 1, 1: 4}], [6, {1: 6}]]")
  expect_equal(fmt(partitions(0)), "[{}]")
  expect_equal(fmt(partitions(8, 2, 3)), "[{}]")
  expect_equal(fmt(multiset_partitions(c(1, 2, 3))), "[[[1, 2, 3]], [[1, 2], [3]], [[1, 3], [2]], [[1], [2, 3]], [[1], [2], [3]]]")
  expect_equal(fmt(multiset_partitions(c(1, 1, 2))), "[[[1, 1, 2]], [[1, 1], [2]], [[1, 2], [1]], [[1], [1], [2]]]")
  expect_equal(fmt(multiset_partitions(c(1, 1, 2, 2), 2)), "[[[1, 1, 2], [2]], [[1, 1], [2, 2]], [[1, 2, 2], [1]], [[1, 2], [1, 2]]]")
  expect_equal(fmt(multiset_partitions(c(1, 1, 1, 2, 3, 3))), "[[[1, 1, 1, 2, 3, 3]], [[1, 1, 1, 2, 3], [3]], [[1, 1, 1, 2], [3, 3]], [[1, 1, 1, 2], [3], [3]], [[1, 1, 1, 3, 3], [2]], [[1, 1, 1, 3], [2, 3]], [[1, 1, 1, 3], [2], [3]], [[1, 1, 1], [2, 3, 3]], [[1, 1, 1], [2, 3], [3]], [[1, 1, 1], [2], [3, 3]], [[1, 1, 1], [2], [3], [3]], [[1, 1, 2, 3, 3], [1]], [[1, 1, 2, 3], [1, 3]], [[1, 1, 2, 3], [1], [3]], [[1, 1, 2], [1, 3, 3]], [[1, 1, 2], [1, 3], [3]], [[1, 1, 2], [1], [3, 3]], [[1, 1, 2], [1], [3], [3]], [[1, 1, 3, 3], [1, 2]], [[1, 1, 3, 3], [1], [2]], [[1, 1, 3], [1, 2, 3]], [[1, 1, 3], [1, 2], [3]], [[1, 1, 3], [1, 3], [2]], [[1, 1, 3], [1], [2, 3]], [[1, 1, 3], [1], [2], [3]], [[1, 1], [1, 2, 3, 3]], [[1, 1], [1, 2, 3], [3]], [[1, 1], [1, 2], [3, 3]], [[1, 1], [1, 2], [3], [3]], [[1, 1], [1, 3, 3], [2]], [[1, 1], [1, 3], [2, 3]], [[1, 1], [1, 3], [2], [3]], [[1, 1], [1], [2, 3, 3]], [[1, 1], [1], [2, 3], [3]], [[1, 1], [1], [2], [3, 3]], [[1, 1], [1], [2], [3], [3]], [[1, 2, 3, 3], [1], [1]], [[1, 2, 3], [1, 3], [1]], [[1, 2, 3], [1], [1], [3]], [[1, 2], [1, 3, 3], [1]], [[1, 2], [1, 3], [1, 3]], [[1, 2], [1, 3], [1], [3]], [[1, 2], [1], [1], [3, 3]], [[1, 2], [1], [1], [3], [3]], [[1, 3, 3], [1], [1], [2]], [[1, 3], [1, 3], [1], [2]], [[1, 3], [1], [1], [2, 3]], [[1, 3], [1], [1], [2], [3]], [[1], [1], [1], [2, 3, 3]], [[1], [1], [1], [2, 3], [3]], [[1], [1], [1], [2], [3, 3]], [[1], [1], [1], [2], [3], [3]]]")
  expect_equal(fmt(multiset_partitions(c(1, 1, 1, 2, 3, 3), 3)), "[[[1, 1, 1, 2], [3], [3]], [[1, 1, 1, 3], [2], [3]], [[1, 1, 1], [2, 3], [3]], [[1, 1, 1], [2], [3, 3]], [[1, 1, 2, 3], [1], [3]], [[1, 1, 2], [1, 3], [3]], [[1, 1, 2], [1], [3, 3]], [[1, 1, 3, 3], [1], [2]], [[1, 1, 3], [1, 2], [3]], [[1, 1, 3], [1, 3], [2]], [[1, 1, 3], [1], [2, 3]], [[1, 1], [1, 2, 3], [3]], [[1, 1], [1, 2], [3, 3]], [[1, 1], [1, 3, 3], [2]], [[1, 1], [1, 3], [2, 3]], [[1, 1], [1], [2, 3, 3]], [[1, 2, 3, 3], [1], [1]], [[1, 2, 3], [1, 3], [1]], [[1, 2], [1, 3, 3], [1]], [[1, 2], [1, 3], [1, 3]]]")
