  expect_equal(fmt(kbins(c(1, 1, 2, 3), 3, ordered = 1)), "[[[1], [1], [2, 3]], [[1], [1], [3, 2]], [[1], [2], [1, 3]], [[1], [2], [3, 1]], [[1], [3], [1, 2]], [[1], [3], [2, 1]], [[2], [1], [1, 3]], [[2], [1], [3, 1]], [[2], [3], [1, 1]], [[3], [1], [1, 2]], [[3], [1], [2, 1]], [[3], [2], [1, 1]]]")
  expect_equal(fmt(multiset_combinations(c(1, 1, 2, 3), 2)), "[[1, 1], [1, 2], [1, 3], [2, 3]]")
  expect_equal(fmt(multiset_combinations(c('b', 'a', 'a', 'a'), 3)), "[['a', 'a', 'a'], ['a', 'a', 'b']]")
