  expect_equal(fmt(strongly_connected_components(list(c(0, 1, 2, 3), list(c(0, 1), c(1, 2), c(2, 3), c(3, 2), c(2, 0))))), "[[0, 1, 2, 3]]")
  expect_equal(fmt(strongly_connected_components(list(1:5, list(c(1, 2), c(2, 1), c(3, 4), c(4, 5), c(5, 3))))), "[[1, 2], [3, 4, 5]]")
  expect_equal(fmt(connected_components(list(0:3, list(c(0, 1), c(1, 2), c(1, 3))))), "[[0, 1, 2, 3]]")
